from pathlib import Path
import sys
if len(sys.argv)!=3: raise SystemExit('usage: patch-offline-runtime99.py INPUT.java OUTPUT.java')
s=Path(sys.argv[1]).read_text(encoding='utf-8')
def once(a,b,label):
 global s
 if s.count(a)!=1: raise ValueError(label+' patch-point count='+str(s.count(a)))
 s=s.replace(a,b,1)
once('import android.content.Context;','import android.content.Context;\nimport android.graphics.Bitmap;\nimport android.graphics.BitmapFactory;','bitmap imports')
once('''    private static final int MAX_RESOURCES = 220;''','''    private static final int MAX_RESOURCES = 220;\n    private static final int MAX_IMAGE_DIMENSION99 = 2400;\n    private static final int WEBP_QUALITY99 = 80;''','image size cap')
helper='''    private static byte[] optimizeImage99(byte[] source, String mime) {\n        if (source == null || source.length < 8192 || mime == null) return null;\n        String type = mime.toLowerCase(Locale.ROOT);\n        if (!type.equals("image/jpeg") && !type.equals("image/png") && !type.equals("image/webp")) return null;\n        Bitmap bitmap = null;\n        try {\n            BitmapFactory.Options bounds = new BitmapFactory.Options();\n            bounds.inJustDecodeBounds = true;\n            BitmapFactory.decodeByteArray(source, 0, source.length, bounds);\n            if (bounds.outWidth <= 0 || bounds.outHeight <= 0) return null;\n            int sample = 1;\n            while (Math.max(bounds.outWidth / sample, bounds.outHeight / sample) > MAX_IMAGE_DIMENSION99) sample *= 2;\n            BitmapFactory.Options options = new BitmapFactory.Options();\n            options.inSampleSize = sample;\n            options.inPreferredConfig = Bitmap.Config.ARGB_8888;\n            bitmap = BitmapFactory.decodeByteArray(source, 0, source.length, options);\n            if (bitmap == null) return null;\n            ByteArrayOutputStream out = new ByteArrayOutputStream();\n            if (!bitmap.compress(Bitmap.CompressFormat.WEBP, WEBP_QUALITY99, out)) return null;\n            byte[] result = out.toByteArray();\n            return result.length < source.length * 0.92 ? result : null;\n        } catch (Throwable ignored) { return null; }\n        finally { if (bitmap != null && !bitmap.isRecycled()) bitmap.recycle(); }\n    }\n\n    private static long optimizeExistingImages99(Context context) throws Exception {\n        File dir = resources(context);\n        File[] entries = dir.listFiles();\n        long saved = 0;\n        if (entries == null) return 0;\n        for (File meta : entries) {\n            if (!meta.isFile() || !meta.getName().endsWith(".mime")) continue;\n            String mime = readSmall(meta, "").toLowerCase(Locale.ROOT);\n            if (!mime.equals("image/jpeg") && !mime.equals("image/png") && !mime.equals("image/webp")) continue;\n            String stem = meta.getName().substring(0, meta.getName().length() - 5);\n            File bin = new File(dir, stem + ".bin");\n            if (!bin.isFile() || bin.length() > 41943040L) continue;\n            byte[] original = readBytes(bin, 41943040L);\n            byte[] compressed = optimizeImage99(original, mime);\n            if (compressed != null && compressed.length < original.length) {\n                long before = bin.length();\n                writeBytes(bin, compressed);\n                writeBytes(meta, "image/webp".getBytes(StandardCharsets.UTF_8));\n                saved += before - bin.length();\n            }\n        }\n        return saved;\n    }\n\n'''
once('''    private static void writeBytes(File file, byte[] bArr) throws Exception {''',helper+'''    private static void writeBytes(File file, byte[] bArr) throws Exception {''','image compression helpers')
old='''                        if (j + fetch.bytes.length > MAX_PAGE_RESOURCES) {\n                            break;\n                        }\n                        writeBytes(fileResourceFile, fetch.bytes);\n                        writeBytes(fileResourceMimeFile, normalizeMime(fetch.contentType).getBytes(StandardCharsets.UTF_8));\n                        linkedHashSet.add(str5);\n                        length = j + fetch.bytes.length;'''
new='''                        String storedMime = normalizeMime(fetch.contentType);\n                        byte[] storedBytes = fetch.bytes;\n                        byte[] imageCompressed = optimizeImage99(fetch.bytes, storedMime);\n                        if (imageCompressed != null) { storedBytes = imageCompressed; storedMime = "image/webp"; }\n                        if (j + storedBytes.length > MAX_PAGE_RESOURCES) {\n                            break;\n                        }\n                        writeBytes(fileResourceFile, storedBytes);\n                        writeBytes(fileResourceMimeFile, storedMime.getBytes(StandardCharsets.UTF_8));\n                        linkedHashSet.add(str5);\n                        length = j + storedBytes.length;'''
once(old,new,'compress newly downloaded images')
needle='''        @JavascriptInterface\n        public String listDownloads() {\n            return OfflineRuntime.publicIndex(this.context).toString();\n        }\n'''
add=needle+'''\n        @JavascriptInterface\n        public void optimizeStorage() {\n            OfflineRuntime.EXEC.execute(new Runnable() {\n                @Override public void run() {\n                    try {\n                        long saved = OfflineRuntime.optimizeExistingImages99(Bridge.this.context);\n                        JSONObject result = OfflineRuntime.event("storage-optimized", "", "", "");\n                        result.put("savedBytes", saved);\n                        result.put("storageBytes", OfflineRuntime.folderSize(OfflineRuntime.root(Bridge.this.context)));\n                        OfflineRuntime.emit(result);\n                    } catch (Throwable error) {\n                        OfflineRuntime.emit(OfflineRuntime.event("storage-optimize-error", "", "", OfflineRuntime.safe(error.getMessage(), 200, "Sıkıştırma başarısız.")));\n                    }\n                }\n            });\n        }\n'''
once(needle,add,'native optimize bridge')
if 'optimizeStorage' not in s or 'Bitmap.CompressFormat.WEBP' not in s: raise ValueError('compression markers missing')
Path(sys.argv[2]).write_text(s,encoding='utf-8')
print('OFFLINE_RUNTIME_99_COMPRESSION_PATCH_OK')
